<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';$u=require_role('OWNER');$method=$_SERVER['REQUEST_METHOD'];if($method==='GET'){$s=db()->prepare('SELECT public_id id,full_name name,email,role,status,last_login_at lastLoginAt,created_at createdAt FROM users WHERE tenant_id=? ORDER BY created_at');$s->execute([$u['tenant_id']]);respond($s->fetchAll());}if($method==='PUT'){require_csrf();$d=input();$id=string_value($d,'id',36);$role=strtoupper((string)($d['role']??''));$status=strtoupper((string)($d['status']??''));if(!in_array($role,['ADMIN','MEMBER'],true)||!in_array($status,['ACTIVE','DISABLED'],true))throw new ApiError(422,'Invalid role or status.');$s=db()->prepare("UPDATE users SET role=?,status=? WHERE tenant_id=? AND public_id=? AND role<>'OWNER'");$s->execute([$role,$status,$u['tenant_id'],$id]);if(!$s->rowCount())throw new ApiError(404,'User not found or unchanged.');audit('user.updated','user',$id,['role'=>$role,'status'=>$status]);respond(['id'=>$id]);}throw new ApiError(405,'Method not allowed.');
